source.header:
@js:
(()=>{
((vb=source.getVariable())&&(String(vb).trim()!='')&&(PHPSESSID=JSON.parse(vb).PHPSESSID))||((PHPSESSID=(()=>{
	  java.toast('生成PHPSESSID')
	  resultstr=String(""); chars='1234567890bcdefghijklmnopqrstuvwxyz'
	  times=(Math.random()*20+15).toFixed(0)
	  while(resultstr.length<times){
	  	  resultstr=String(`${resultstr}${(()=>{
       random=Math.random()
       cindex=Math.floor(random*chars.length)
       return chars.charAt(cindex)
	    })()}`)
	  }
	  return resultstr
})())&&(source.setVariable(JSON.stringify({
	  "PHPSESSID":PHPSESSID,
	  "ver_code":"8210"
}))))
return JSON.stringify({
	   "upgrade-insecure-requests":"1",
	   "user-agent":"Mozilla/5.0 (iPad; Android 12; Redmi; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/96.0.4664.104 Mobile Safari/537.36",
	   "accept":"text/html",
	   "referer":"https://www.haoman8.com",
	   "Cookie":`PHPSESSID=${PHPSESSID}`
})})()

