@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
push("全部🌊分类",null,1,1)
	arList=[["小说","arttype/1000"],["有声小说","arttype/5032"],["爱情","arttype/5031"],["故事","arttype/1002"],["淫乱乱伦","arttype/1003"],["现代","arttype/5005"],["人妻熟女","arttype/1001"],["学生","arttype/1004"],["仙侠武侠","arttype/1005"],["暴力侵犯","arttype/5004"],["其它","arttype/5003"]]
	arList.map(([tag,uri])=>{
		url=`/${uri}<,-{{page}}/>`;
		push(tag, url, 1, 0.25);
		});
//java.log(JSON.stringify(sort))
JSON.stringify(sort)

